const crypto = require('crypto');
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

const reminderId = crypto.randomUUID();
const content = 'Aurora Smart Desk Lamp Pro (PROD-73FAB4) — Price: \$88.00. Currently in stock. Includes a 12-month manufacturer warranty and a 30-day return window.';
const creationTimestamp = 1788228000;  // matching existing pattern: 2026-09-01T10:00:00 UTC
const reminderTimestamp = 1788228000;  // same base timestamp
const createdAt = '2026-09-01T10:00:00';

const stmt = db.prepare('INSERT INTO ts_reminders (reminder_id, content, creation_timestamp, reminder_timestamp, latitude, longitude, created_at) VALUES (?, ?, ?, ?, NULL, NULL, ?)');
stmt.run(reminderId, content, creationTimestamp, reminderTimestamp, createdAt);

// Verify
const row = db.prepare('SELECT * FROM ts_reminders WHERE reminder_id = ?').get(reminderId);
console.log('Inserted reminder:');
console.log(JSON.stringify(row, null, 2));
"
